from src.graph_coloring import greedy_color, chromatic_number


def test_bipartite_two_colors():
    # Cycle of 4 nodes is bipartite — needs 2 colors
    adj = {0: [1, 3], 1: [0, 2], 2: [1, 3], 3: [2, 0]}
    colors = greedy_color(adj)
    assert colors[0] != colors[1]
    assert colors[1] != colors[2]
    assert colors[2] != colors[3]
    assert colors[3] != colors[0]
    assert chromatic_number(adj) == 2


def test_triangle_three_colors():
    # K3 needs 3 colors
    adj = {0: [1, 2], 1: [0, 2], 2: [0, 1]}
    colors = greedy_color(adj)
    assert colors[0] != colors[1]
    assert colors[0] != colors[2]
    assert colors[1] != colors[2]
    assert chromatic_number(adj) == 3


def test_no_edges_one_color():
    adj = {0: [], 1: [], 2: []}
    assert chromatic_number(adj) == 1


def test_valid_coloring_path():
    # Path 0-1-2-3 is bipartite
    adj = {0: [1], 1: [0, 2], 2: [1, 3], 3: [2]}
    colors = greedy_color(adj)
    for v, neighbors in adj.items():
        for u in neighbors:
            assert colors[v] != colors[u], f"conflict at edge {v}-{u}"


def test_single_node():
    adj = {0: []}
    assert chromatic_number(adj) == 1
